def quick_sort(arr, low=0, high=None):
    if high is None:
        high = len(arr) - 1
    if low < high:
        pi = partition(arr, low, high)   # partition index
        quick_sort(arr, low, pi - 1)     # sort left of pivot
        quick_sort(arr, pi + 1, high)    # sort right of pivot
    return arr

def partition(arr, low, high):
    pivot = arr[high]     # choose last element as pivot
    i = low - 1           # index of smaller element
    for j in range(low, high):
        if arr[j] <= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]  # swap
    arr[i+1], arr[high] = arr[high], arr[i+1] # place pivot
    return i + 1          # return pivot index

print(quick_sort([10, 7, 8, 9, 1, 5]))
# [1, 5, 7, 8, 9, 10]

# Randomised pivot — avoids worst case
import random
def partition_random(arr, low, high):
    rand = random.randint(low, high)
    arr[rand], arr[high] = arr[high], arr[rand]  # swap random to end
    return partition(arr, low, high)
